// DeleteOne soft deletes a single Passage record by ID
func (r *PassageRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE passage SET deleted_at = $1 WHERE id = $2 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

// DeleteMany soft deletes multiple Passage records matching the filter
